const COLUMNS = ['symbol', 'w', 'm', 'q', 'h', 'y', 'y2', 'score'] as const;
  const NUMERIC = ['w', 'm', 'q', 'h', 'y', 'y2', 'score'] as const;

  const raw = rankingMap[id] as unknown;
  if (!Array.isArray(raw)) return undefined;
  if (raw.length === 0) return [];

  const entries = raw.map((row) =>
    Array.isArray(row)
      ? Object.fromEntries(COLUMNS.map((key, i) => [key, row[i]]))
      : row
  ) as Record<string, unknown>[];

  const filtered = entries.filter(
    (e) => typeof e['symbol'] === 'string' && !/\d/.test(e['symbol'] as string)
  );
  if (filtered.length === 0) return [];

  const stats = Object.fromEntries(
    NUMERIC.map((key) => {
      const values = filtered.map((e) => Number(e[key])).filter(Number.isFinite);
      const min = values.length ? Math.min(...values) : 0;
      const max = values.length ? Math.max(...values) : 0;
      return [key, { min, max }];
    })
  ) as Record<string, { min: number; max: number }>;

  const normalized = filtered.map((entry) => {
    const next = { ...entry } as Record<string, unknown>;
    for (const key of NUMERIC) {
      const { min, max } = stats[key];
      const v = Number(entry[key]);
      next[key] = !Number.isFinite(v) ? NaN : max === min ? 0 : ((v - min) / (max - min)) * 100;
    }
    return next as unknown as FinanceRankingUpdateResponse;
  });

  return normalized.sort((a, b) => {
    const av = Number(a.score);
    const bv = Number(b.score);
    if (!Number.isFinite(av) && !Number.isFinite(bv)) return 0;
    if (!Number.isFinite(av)) return 1;
    if (!Number.isFinite(bv)) return -1;
    return bv - av;
  });

